      uz: 'Talaba bo‘lganingiz uchun budjetingiz katta emasligini, universitetdan uzoq uyda transport xarajati ko‘p bo‘lishi sabab ijara biroz qimmatroq bo‘lsa ham universitetga yaqin uy tanlamoqchi ekaningizni yozing.',
      en: 'Write that because you are a student your budget is limited, and because a home far from school creates high transportation costs, you would rather choose a home near school even if its rent is slightly higher.',
