  // Node 6 · 13과 교재 세부까지 완성해요
  //
  // Unit 13 전체 재검수 보충 Node
  //
  // Lesson 1 601-624 · 집과 생활비 어휘를 정확히 구별해요
  // Lesson 2 625-648 · 어디가 좋을지 모르겠어요
  // Lesson 3 649-672 · 좋기는 하지만 단점도 있어요
  // Lesson 4 673-696 · 이유와 생활 편의를 연결해요
  // Lesson 5 697-720 · 교재 마지막 세부까지 확인해요
  //
  // pp.92-99 세부 연습 회수
  // p.105 읽기 판별 보강
  // p.109 발음 준비/연습 문장 회수
  // p.110 자기평가 최종 통합
  //
  // 5 Lessons × 24 = 120
  // builder trio = 15 / 24 = 62.5%
  // dialog_complete = 0
  // ══════════════════════════════════════════════════════════

